interface.definition:
a!localVariables(
  local!audithistory: #"_a-0000e6b8-3009-8000-9bf7-011c48011c48_3442778"(requestId: ri!nomination.nominationId, ).data,
  local!isMarkedCompleteDate: index(
    index(local!audithistory,"createdOn",{}),
    wherecontains(
      tostring(#"_a-0000ef1d-53c4-8000-9c6a-011c48011c48_14227992"),
      touniformstring(local!audithistory.action)
    ),
    {}
  ),
  local!updateverbiage: if(
    a!isNullOrEmpty(ri!nomination.createdOn),
    true,
    if(
      todatetime(ri!nomination.createdOn) > #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12333392",
      true,
      if(
        contains(#"_a-0000eb38-82c9-8000-9c51-011c48011c48_12539426", ri!nomination.statusId),
        false,
        true
      )
    )
  ),
  local!isRequestAfterV4: if(
    a!isNullOrEmpty(ri!nomination.createdOn),
    true,
    if(
      todatetime(ri!nomination.createdOn)> #"_a-0000eab6-1962-8000-9c4d-011c48011c48_12333392",
      true,
      false
    )
  ),
  local!isrequestAfterV4Deployment: if(
    a!isNullOrEmpty(ri!nomination.createdOn),
    true,
    if(
      todatetime(ri!nomination.createdOn) > #"_a-0000ebe3-046c-8000-9c56-011c48011c48_13092616",
      true,
      false
    )
  ),
  local!isrequestAfterV5Deployment: if(
    a!isNullOrEmpty(ri!nomination.createdOn),
    true,
    if(
      todatetime(ri!nomination.createdOn) > #"_a-0000ef1d-53c4-8000-9c6a-011c48011c48_14165460",
      true,
      if(
        or(
          a!isNullOrEmpty(local!isMarkedCompleteDate),
          and(
            a!isNotNullOrEmpty(local!isMarkedCompleteDate),
            todatetime(local!isMarkedCompleteDate) > #"_a-0000ef1d-53c4-8000-9c6a-011c48011c48_14165460"
          )
        ),
        true,
        false()
      )
    ),

  ),
{
  #"SYSTEM_SYSRULES_sectionLayout_v1"(
    label: "Candidate Details",
    labelColor: "SECONDARY",
    contents: {
      #"SYSTEM_SYSRULES_cardLayout"(
        contents: {
          #"SYSTEM_SYSRULES_columnsLayout"(
            columns: {
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_textField"(
                    label: "Candidate Name",
                    value: #"_a-0000e6d2-8270-8000-9c03-011c48011c48_3928917"(
                      firstName: ri!nomination.firstName,
                      middleName: ri!nomination.middleName,
                      lastName: ri!nomination.lastName
                    ),
                    readOnly: true
                  ),
                  #"SYSTEM_SYSRULES_textField"(
                    label: "Effective DPP Start Date",
                    value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
                      value: ri!candidateDetails.candidateProjectedStartDate,
                      isBoolean: false
                    ),
                    readOnly: true
                  ),
                  #"SYSTEM_SYSRULES_textField"(
                    label: "DPP Group",
                    value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
                      value: ri!candidateDetails.dppGroup,
                      isBoolean: false
                    ),
                    readOnly: true
                  ),
                  if(toboolean(local!isrequestAfterV4Deployment) = true,
                  #"SYSTEM_SYSRULES_textField"(
                    label: "Other DPP Group",
                    value: ri!candidateDetails.dppGroupOther,
                    readOnly: true,
                    showWhen: and(
                      local!isrequestAfterV4Deployment,
                      ri!candidateDetails.dppGroup = "Other"
                    )
                  ), #"SYSTEM_SYSRULES_textField"(
                    label: "Other DPP Group",
                    value: ri!candidateDetails.dppGroupOther,
                    readOnly: true,
                    showWhen: and(
                      local!isRequestAfterV4,
                      ri!candidateDetails.dppGroup = "Other"
                    )
                  ),

                  ),
                  #"SYSTEM_SYSRULES_textField"(
                    label: "New Business Area",
                    value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: ri!candidateDetails.newBusinessArea),
                    readOnly: true
                  ),

                }
              ),
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_textField"(
                    label: "Position Type",
                    value: 
                    displayvalue(
                      tointeger(ri!candidateDetails.positionType),
                      index(ri!refData, "refId", {}),
                      index(ri!refData, "description",{}),
                      null
                    ),
                    readOnly: true
                  ),
                  #"SYSTEM_SYSRULES_textField"(
                    label: "Effective System Transfer Date",
                    value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
                      value: ri!candidateDetails.effectiveTransferDate
                    ),
                    readOnly: true
                  ),
                  #"SYSTEM_SYSRULES_textField"(
                    label: "New Geo Location",
                    value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: ri!candidateDetails.newGeoLocation),
                    readOnly: true
                  ),

                }
              ),
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_textField"(
                    label: "Position Sub Type",
                    value:
                    displayvalue(
                      tointeger(ri!candidateDetails.subPosition),
                      index(ri!subPositionTypes, "subPositionId", {}),
                      index(ri!subPositionTypes, "subPosition",{}),
                      null
                    ),
                    readOnly: true
                  ),
                  #"SYSTEM_SYSRULES_textField"(
                    label: "Effective End Date",
                    value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
                      value: ri!candidateDetails.rotationEndDate
                    ),
                    readOnly: true
                  ),
                  #"SYSTEM_SYSRULES_textField"(
                    label: "Originating Audit BU",
                    value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: ri!candidateDetails.originatingBU),
                    readOnly: true,
                    showWhen: and(toboolean(local!isrequestAfterV5Deployment) = true,
                    not(ri!nomination.isDirectHire = true),
                  )),
                  #"SYSTEM_SYSRULES_textField"(
                    label: "Other Originating Audit BU",
                    value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: ri!candidateDetails.OtheroriginatingBU),
                    readOnly: true,
                    showWhen: and(
                      toboolean(local!isrequestAfterV5Deployment) = true,
                      not(ri!nomination.isDirectHire = true),
                      ri!candidateDetails.originatingBU = #"_a-0000eb38-82c9-8000-9c51-011c48011c48_12423181"
                    ) = true
                  ),

                  #"SYSTEM_SYSRULES_textField"(
                    label: "Originating Home Office",
                    value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: ri!candidateDetails.originatingHomeOffice),
                    readOnly: true,
                    showWhen: and(toboolean(local!isrequestAfterV5Deployment) = true,
                    not(ri!nomination.isDirectHire = true),
                  )),
                  #"SYSTEM_SYSRULES_textField"(
                    label: "Other Originating Home Office",
                    value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: ri!candidateDetails.otherOriginatingHomeOffice),
                    readOnly: true,
                    showWhen: and(
                      toboolean(local!isrequestAfterV5Deployment) = true,
                      not(ri!nomination.isDirectHire = true),
                      ri!candidateDetails.originatingHomeOffice = #"_a-0000eb38-82c9-8000-9c51-011c48011c48_12423181"
                    ) = true
                  )

                }
              ),
              #"SYSTEM_SYSRULES_columnLayout"(
                contents: {
                  #"SYSTEM_SYSRULES_textField"(
                    label: "New Cost Center",
                    value: ri!candidateDetails.costCenter,
                    readOnly: true
                  ),
                  #"SYSTEM_SYSRULES_textField"(
                    label: "Returning Audit BU",
                    value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: ri!candidateDetails.returningBU),
                    readOnly: true,
                    showWhen: and(toboolean(local!isrequestAfterV5Deployment) = true,
                    not(ri!nomination.isDirectHire = true),)
                  ),
                  #"SYSTEM_SYSRULES_textField"(
                    label: "Other Returning Audit BU",
                    value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: ri!candidateDetails.otherReturningBU),
                    readOnly: true,
                    showWhen: and(
                      toboolean(local!isrequestAfterV5Deployment) = true,
                      not(ri!nomination.isDirectHire = true),
                      ri!candidateDetails.returningBU = #"_a-0000eb38-82c9-8000-9c51-011c48011c48_12423181"
                    ) = true
                  ),
                  #"SYSTEM_SYSRULES_textField"(
                    label: "Returning Home Office",
                    value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: ri!candidateDetails.returningHomeOffice),
                    readOnly: true,
                    showWhen: toboolean(local!isrequestAfterV5Deployment) = true
                  ),
                  #"SYSTEM_SYSRULES_textField"(
                    label: "Other Returning Home Office",
                    value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(value: ri!candidateDetails.OtherReturningHomeOffice),
                    readOnly: true,
                    showWhen: and(
                      toboolean(local!isrequestAfterV5Deployment) = true,
                      ri!candidateDetails.returningHomeOffice = #"_a-0000eb38-82c9-8000-9c51-011c48011c48_12423181"
                    ) = true
                  ),
                  #"SYSTEM_SYSRULES_textField"(
                    label: "Returning Office",
                    value: if(
                      #"_a-0000e676-ab43-8000-9bf5-011c48011c48_3050228"(ri!nomination.returnHomeOffice),
                      "N/A",
                      ri!nomination.returnHomeOffice
                    ),
                    readOnly: true,
                    showWhen: and(toboolean(local!isrequestAfterV4Deployment) = true,toboolean(local!isrequestAfterV5Deployment) = false)
                  ),
                  #"SYSTEM_SYSRULES_textField"(
                    label: "Non-Traditional Rotational Type",
                    /*value: if(*/
                      /*ri!nomination.nonTraditionalTypeId=cons!CAW_INT_NON_TRAD_ROTATIONAL_TYPE_ID,*/
                      /*cons!CAW_TXT_NON_TRAD_ROTATIONAL_TYPE,*/
                      /*{}*/
                    /*),*/
                    /*readOnly: true,*/
                    /*showWhen: and(*/
                      /*a!isNotNullOrEmpty(ri!nomination.nonTraditionalTypeId),*/
                      /*ri!nomination.nonTraditionalTypeId=cons!CAW_INT_NON_TRAD_ROTATIONAL_TYPE_ID,*/
                    /*)*/
                    value: if(
                      tointeger(ri!candidateDetails.nonTradRotationalType) = #"_a-0000ef1d-53c4-8000-9c6a-011c48011c48_14179166",
                      #"_a-0000ef1d-53c4-8000-9c6a-011c48011c48_14179180",
                      tostring(index(#"_a-0000ea45-eea9-8000-9c49-011c48011c48_11599196"(
                        isActive: true,
                        nonTradRotationId: { tointeger(ri!candidateDetails.nonTradRotationalType) }
                      ),"nontradrotationaltype",{}))
                    ),
                    readOnly: true,
                    showWhen: tointeger(ri!candidateDetails.subPosition) = #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11599223"
                  ),
                  #"SYSTEM_SYSRULES_textField"(
                    label: "Other Non-Traditional Rotational Type",
                    value: if(
                      and(
                        tointeger(ri!candidateDetails.nonTradRotationalType) =#"_a-0000ef1d-53c4-8000-9c6a-011c48011c48_14179166",
                        a!isNotNullOrEmpty( (ri!candidateDetails.otherNonTraditionalRotationType)),
                        ),
                        (ri!candidateDetails.otherNonTraditionalRotationType),
                      {}
                    ),
                    readOnly: true,
                    showWhen: and(
                      a!isNotNullOrEmpty (ri!candidateDetails.otherNonTraditionalRotationType),
                      a!isNotNullOrEmpty(tointeger(ri!candidateDetails.nonTradRotationalType)) ,
                      tointeger(ri!candidateDetails.nonTradRotationalType) =#"_a-0000ef1d-53c4-8000-9c6a-011c48011c48_14179166",
                      tointeger(ri!candidateDetails.subPosition) = #"_a-0000ea45-eea9-8000-9c49-011c48011c48_11599223",
                    )

                  ),
                }
              )
            }
          )
        },
        marginBelow: "STANDARD"
      ),
      #"SYSTEM_SYSRULES_cardLayout"(
        contents: {
          if(
            toboolean(local!updateverbiage) = TRUE,
            {
              fn!richTextEditorField(
                richTextValue: #"_a-0000eb38-82c9-8000-9c51-011c48011c48_12517210",
                isReadOnly: true,

              )
            },
            {
          #"SYSTEM_SYSRULES_linkField"(
            label: "CPA License",
            instructions: "Firm policy requires all Audit Managers, Senior Managers, Partners, and Tax & Advisory Professionals who are CPA eligible, to have a current, active CPA license to practice in the state in which his/her office is located. For any rotational transferring to NYC, it is mandatory that you complete the application and submit all required documentation to the NY State Board of Accountancy before you begin your rotation. Please be aware that licensure in New York State can take several months. Once your license has been awarded, please submit the documentation to the HRSC. For those as applicable, we ask that you hold off on starting this process at this time until communicated to do so by the DPP Operations team.",
            links: {
              #"SYSTEM_SYSRULES_safeLink"(
                label: "Professional License Certification Form",
                uri: "http://hrscforms.us.kworld.kpmg.com/hrsc/pdf/Professional License.doc"
              )
            }
          ),
          #"SYSTEM_SYSRULES_linkField"(
            label: "Independence",
            instructions: "Managers and above are required to complete an Independence Affidavit as part of joining the Department. Upon your start date with the department, you will receive a link to the Independence Affidavit which is required to be completed within 5 business days.",
            links: {
              #"SYSTEM_SYSRULES_safeLink"(
                label: "Independence Notice for Senior Managers and Managers in DPP",
                uri: "https://portal.us.kworld.kpmg.com/audit/AuditRepository/DRT-Independence%20Notice%20for%20DPP%20Senior%20Managers_2020.docx?Web=1"
              ),
              #"SYSTEM_SYSRULES_safeLink"(
                label: "Independence Notice for Partners and Audit Managing Directors in DPP",
                uri: "https://portal.us.kworld.kpmg.com/audit/AuditRepository/DRT-Independence%20Notice%20for%20DPP%20Partners%20and%20MDs_2020.docx?Web=1"
              )
            }
          ),
          #"SYSTEM_SYSRULES_richTextDisplayField"(
            label: "Transitional Core End Date Agreement",
            value: #"SYSTEM_SYSRULES_richTextItem_v1"(
              text:  "At the end of the 2 year transitional period, a determination by the transferee and DPP will be made as to whether the transferee becomes permanent core within DPP or returns back to their home BU/office."
            ),
            showWhen: ri!nomination.subPositionTypeId = #"_a-0000e6eb-1d17-8000-9c08-011c48011c48_4147895"
          ),
          }
          ),
          #"SYSTEM_SYSRULES_paragraphField"(
            label: "Other Information - DPP",
            instructions: "DPP Orientation will be held in late June (subject to change). Attendance is required. Further communication will be sent at a later date.",
            value: #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
              value: ri!candidateDetails.otherInformation,
              isBoolean: false
            ),
            readOnly: true
          )
        },
        marginBelow: "STANDARD"
      )
    },
    showWhen: ri!showWhen,
    isCollapsible: true,
    divider: "ABOVE",
    dividerWeight: "MEDIUM",
    dividerColor: "SECONDARY",
    marginBelow: "STANDARD"
  ),
  #"SYSTEM_SYSRULES_sectionLayout_v1"(
    label: "Additional Comments",
    labelColor: "SECONDARY",
    contents: {
      #"SYSTEM_SYSRULES_paragraphField"(
        label: "DPP Additional Note",
        value:  #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
          value:  ri!candidateDetails.dppTransferConfirmationNote,
          isBoolean: false
        ),
        readOnly: true
      ),
      #"SYSTEM_SYSRULES_paragraphField"(
        label: "Candidate Additional Note",
        value:   #"_a-0000e69d-7e03-8000-9bf6-011c48011c48_3412447"(
          value:  ri!candidateDetails.candidateTransferConfirmationNote,
          isBoolean: false
        ),
        readOnly: true
      )
    },
    showWhen: and(
      not(ri!nomination.isDirectHire = true),
      ri!showWhen
    ),
    isCollapsible: true,
    divider: "ABOVE",
    dividerWeight: "MEDIUM",
    dividerColor: "SECONDARY",
    marginBelow: "STANDARD"
  ),
  #"SYSTEM_SYSRULES_sectionLayout_v1"(
    label: "Acknowledgement",
    labelColor: "SECONDARY",
    contents: {
      #"SYSTEM_SYSRULES_cardLayout"(
        contents: {
          #"SYSTEM_SYSRULES_checkboxField"(
            label: "Candidate Acknowledgement",
            choiceLabels: {"I acknowledge the DPP terms and conditions of this transfer confirmation"},
            choiceValues: {true},
            value: if(
              ri!nomination.statusId = #"_a-0000e7f4-9a94-8000-9c23-011c48011c48_6445262",
              null,
              ri!candidateDetails.isTransferConfirmationAck
            ),
            disabled: true
          )
        },
        showWhen: true,
        marginBelow: "STANDARD"
      )
    },
    showWhen: and(
      not(ri!nomination.isDirectHire = true),
      ri!showWhen
    ),
    isCollapsible: true,
    divider: "ABOVE",
    dividerWeight: "MEDIUM",
    dividerColor: "SECONDARY",
    marginBelow: "STANDARD"
  )
}
)
